const name = await Dialog.prompt('请输入名字');
if (name === null) return;   // 用户取消了
// 带校验：
const pw = await Dialog.prompt('密码', {
  inputType: 'password',
  validate: (v) => v.length < 6 ? '至少 6 位' : undefined,
});

Dialog.tips('已保存');                          // 5 秒后自动消失
Dialog.tips('出错了', { type: 'error' });
Dialog.tips('加载中…', { timeout: 0 });       // 常驻，返回句柄可 close()

const l = Dialog.loading('加载中…');
try {
  await doWork();
} finally {
  l.close();
}

const p = Dialog.progress('上传中…', { type: 'bar' });
p.set(45);                 // 45%
p.set(45, '已传 4.5MB');   // 顺带换文案
p.close();

// 四种样式：bar / circle / dots / steps
Dialog.progress('不知道要多久', { type: 'dots' });   // 不确定进度
